WITH last_solar AS (
  SELECT ts, solar_kw FROM microgrid_minute WHERE $__timeFilter(ts) AND solar_kw IS NOT NULL ORDER BY ts DESC LIMIT 1
), last_soc AS (
  SELECT ts, battery_soc_pct FROM microgrid_minute WHERE $__timeFilter(ts) AND battery_soc_pct IS NOT NULL ORDER BY ts DESC LIMIT 1
), last_charger AS (
  SELECT DISTINCT ON (wallbox_id) wallbox_id, ts, power_kw FROM charger_minute WHERE $__timeFilter(ts) ORDER BY wallbox_id, ts DESC
), last_status AS (
  SELECT DISTINCT ON (wallbox_id) wallbox_id, ts, status FROM connector_event WHERE ts <= $__timeTo() ORDER BY wallbox_id, ts DESC
)
SELECT 'solar' AS kind, 'PV' AS id, 'SOLAR ARRAY' AS label, solar_kw::double precision AS value, ts AS observed_at, NULL::text AS status FROM last_solar
UNION ALL SELECT 'battery','BATTERY','BATTERY · SOC',battery_soc_pct::double precision,ts,NULL FROM last_soc
UNION ALL SELECT 'hub','HUB','SITE BUS',NULL::double precision,NULL::timestamptz,NULL::text
UNION ALL SELECT 'charger',w.id,w.id,c.power_kw::double precision,c.ts,s.status FROM wallbox w LEFT JOIN last_charger c ON c.wallbox_id=w.id LEFT JOIN last_status s ON s.wallbox_id=w.id

