const frame = context.panel.data.series[0];
const fields = Object.fromEntries((frame?.fields || []).map(f => [f.name, f.values?.buffer || f.values || []]));
const n = fields.id?.length || 0;
const rows = Array.from({length:n}, (_,i) => Object.fromEntries(Object.entries(fields).map(([k,v]) => [k,v[i]])));
const dark=context.grafana.theme.isDark;
const ink=dark?'#DDE9F4':'#17324A', muted=dark?'#91A4B7':'#50677C', border=dark?'#54708C':'#89A2B9';
const colors = {solar:'#F6BE69', battery:'#A8A3FA', hub:'#7D91AB', charger:'#5BE5D5'};
const yPositions = [42,102,162,222,282,342,402,462];
const chargerRows = rows.filter(r=>r.kind==='charger').sort((a,b)=>a.id.localeCompare(b.id));
const nodes = rows.map(r => {
  const idx = chargerRows.findIndex(c=>c.id===r.id);
  const x = r.kind==='solar' ? 95 : r.kind==='battery' ? 95 : r.kind==='hub' ? 325 : 555;
  const y = r.kind==='solar' ? 155 : r.kind==='battery' ? 350 : r.kind==='hub' ? 250 : yPositions[idx];
  const fresh = r.value !== null && r.value !== undefined;
  const suffix = r.kind==='battery' ? '%' : r.kind==='hub' ? '' : ' kW';
  const stat = r.kind==='hub' ? 'configured' : fresh ? Number(r.value).toFixed(1)+suffix : 'no reading';
  return {id:r.id, name:r.label+'\n'+stat, x, y, value:r.value, observed_at:r.observed_at, status:r.status,
    kind:r.kind, symbolSize:r.kind==='hub'?76:r.kind==='charger'?48:67,
    itemStyle:{color:fresh || r.kind==='hub' ? colors[r.kind] : '#485669', borderColor:'#D8E5F4', borderWidth:1, shadowBlur:18, shadowColor:colors[r.kind]+'66'},
    label:{show:true, position:r.kind==='hub'?'inside':'right', color:ink,
      fontSize:r.kind==='charger'?11:12, lineHeight:16, distance:11}};
});
const links = [{source:'PV',target:'HUB'}, {source:'BATTERY',target:'HUB'},
  ...chargerRows.map(r=>({source:'HUB',target:r.id}))];
context.panel.chart.off('click');
context.panel.chart.on('click', p => {
  if (p.dataType==='node' && p.data.kind==='charger') {
    const from=context.grafana.replaceVariables('${__from}');
    const to=context.grafana.replaceVariables('${__to}');
    context.grafana.locationService.push('/d/sofie-fleet?from='+encodeURIComponent(from)+'&to='+encodeURIComponent(to)+'&timezone=Europe%2FBerlin&var-wallbox='+encodeURIComponent(p.data.id));
  }
});
return {backgroundColor:'transparent', animationDuration:500,
  tooltip:{trigger:'item',backgroundColor:dark?'#142235':'#FFFFFF',borderColor:border,textStyle:{color:ink},
    formatter:p=>p.dataType==='edge' ? 'Configured connection · flow not measured' :
    `${p.data.id}<br/>${p.data.value == null ? 'No measurement in range' : Number(p.data.value).toFixed(2)+(p.data.kind==='battery'?'%':' kW')}`+
    (p.data.status ? `<br/>Last event: ${p.data.status}` : '')+
    (p.data.observed_at ? `<br/>Measured: ${new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',dateStyle:'short',timeStyle:'short'}).format(new Date(p.data.observed_at))}` : '')},
  series:[{type:'graph',layout:'none',roam:true,data:nodes,links,
    lineStyle:{color:border,width:1.6,opacity:.85,curveness:.08,type:'dashed'},
    emphasis:{focus:'adjacency',lineStyle:{width:3}}, edgeSymbol:['none','none']}],
  graphic:[{type:'text',left:18,top:12,style:{text:'CONFIGURED TOPOLOGY  •  SELECTED WINDOW',fill:muted,font:'11px sans-serif'}},
    {type:'text',left:18,bottom:10,style:{text:'Select a wallbox for fleet detail. Links show topology, not measured flow.',fill:muted,font:'11px sans-serif'}}]};

const frame=context.panel.data.series[0];
const f=Object.fromEntries((frame?.fields||[]).map(x=>[x.name,x.values?.buffer||x.values||[]]));
const dark=context.grafana.theme.isDark;
const ink=dark?'#DDE9F4':'#17324A', muted=dark?'#91A4B7':'#50677C', border=dark?'#54708C':'#89A2B9';
const n=f.wallbox_id?.length||0;
const rows=Array.from({length:n},(_,i)=>({time:new Date(f.bucket[i]).getTime(),box:String(f.wallbox_id[i]),kw:Number(f.avg_kw[i])}));
const times=[...new Set(rows.map(r=>r.time))].sort((a,b)=>a-b);
const boxes=[...new Set(rows.map(r=>r.box))].sort();
const max=Math.max(1,...rows.map(r=>r.kw));
const data=rows.map(r=>[times.indexOf(r.time),boxes.indexOf(r.box),r.kw]);
return {backgroundColor:'transparent',animationDuration:350,
  grid:{left:62,right:28,top:20,bottom:68},
  tooltip:{position:'top',backgroundColor:dark?'#142235':'#FFFFFF',borderColor:border,textStyle:{color:ink},
    formatter:p=>`${boxes[p.data[1]]}<br/>${new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',dateStyle:'short',timeStyle:'short'}).format(new Date(times[p.data[0]]))}<br/><b>${p.data[2].toFixed(2)} kW average</b>`},
  xAxis:{type:'category',data:times.map(t=>new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(t))),
    axisLabel:{color:muted,interval:Math.max(0,Math.floor(times.length/8)-1),rotate:0},axisLine:{lineStyle:{color:border}},splitArea:{show:false}},
  yAxis:{type:'category',data:boxes,axisLabel:{color:ink},axisLine:{lineStyle:{color:border}}},
  visualMap:{min:0,max,calculable:false,orient:'horizontal',left:'center',bottom:0,
    text:['HIGH','LOW'],textStyle:{color:muted},inRange:{color:['#183344','#245F70','#40B9B0','#F6BE69']}},
  series:[{type:'heatmap',data,itemStyle:{borderColor:dark?'#142235':'#FFFFFF',borderWidth:1},emphasis:{itemStyle:{borderColor:'#FFFFFF',borderWidth:1}}}]};
